# Terminal, case-specific preservation. No boot/restore/force, activation,
# journal/packed read, replay or source availability change is provided here.
[CmdletBinding()]param(
    [Parameter(Mandatory)][ValidateSet('Finalize','Rollback')][string]$Operation,
    [Parameter(Mandatory)][guid]$ExpectedParentGuid,
    [Parameter(Mandatory)][ValidateRange(45,46)][int]$ExpectedCheckpointCount
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$Operation=if($Operation -ieq 'Finalize'){'Finalize'}else{'Rollback'}
$workspace='D:\code\ntfs2refs';$base=Join-Path $workspace '.lab\hyperv\streaming-v2-20261027'
$case=Join-Path $base 'compact-admitted-interrupt-20261028';$root=Join-Path $base ('compact-admitted-recovery-20261028\'+$Operation.ToLowerInvariant())
$id=[guid]'2401593c-4b30-472e-9b6d-c9534cbaa599';$original='949dbc98138e4514a1098081eb0226ef';$partial=[guid]'554482bb-f2a4-4185-8023-09d60465137f'
function Need([bool]$Condition,[string]$Message){if(-not$Condition){throw $Message}}
function Hash([byte[]]$Bytes){$s=[Security.Cryptography.SHA256]::Create();try{[BitConverter]::ToString($s.ComputeHash($Bytes)).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Read-HostJson([string]$Path){$m=Get-Item -LiteralPath $Path -Force;Need (-not$m.PSIsContainer -and -not($m.Attributes -band [IO.FileAttributes]::ReparsePoint) -and $m.Length -gt 0 -and $m.Length -le 4MB) 'Ordinary bounded host JSON required.';Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json}
function Save-New([string]$Name,$Value){$b=[Text.UTF8Encoding]::new($false).GetBytes(($Value|ConvertTo-Json -Depth 16));Need ($b.Length -le 4MB) 'Host receipt exceeds4MiB.';$f=[IO.File]::Open((Join-Path $root $Name),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$f.Write($b,0,$b.Length);$f.Flush($true)}finally{$f.Dispose()}}
Need ($ExpectedParentGuid -eq $partial -and $ExpectedCheckpointCount -eq $(if($Operation -ceq 'Finalize'){45}else{46})) 'Use partial45 as parent, count45 for Finalize or46 for Rollback.'
foreach($name in @('preservation-intent.json','checkpoint-create-intent.json','preserved-checkpoint.json','preservation-failed.json')){Need (-not(Test-Path -LiteralPath (Join-Path $root $name))) 'Role preservation has state; inspect instead of repeating actions.'}
$d=Read-HostJson (Join-Path $root 'dispatch.json');$enrollment=Read-HostJson (Join-Path $root 'intent.json');$observation=Read-HostJson (Join-Path $case 'partial-journal-observation.json');$saved=Read-HostJson (Join-Path $case 'partial-checkpoint.json')
Need ($saved.success -eq $true -and [guid]$saved.checkpoint_id -eq $partial -and $saved.run_id -ceq $original -and $saved.checkpoint_count -eq 45) 'Original preserved partial45 differs.'
Need ([guid]$d.vm_id -eq $id -and $d.original_run_id -ceq $original -and $d.operation -ceq $Operation -and $d.expected_exit -eq 0 -and $d.task_name -ceq ('N2R-AdmittedCompactRecovery-'+$Operation+'-'+$d.run_id) -and $d.guest_stage -ceq ('C:\ntfs2refs\admitted-compact-recovery-'+$Operation.ToLowerInvariant()+'-'+$d.run_id) -and $d.output_dir -ceq (Join-Path $d.guest_stage 'result') -and [guid]$enrollment.parent_id -eq $ExpectedParentGuid) 'Exact recovery role dispatch/enrollment required.'
$originalPins=@{};foreach($doc in $observation.documents){$originalPins[$doc.name]=$doc.sha256}
foreach($spec in @(@('request.json','request_sha256'),@('ticket.json','ticket_sha256'),@('expectation.json','expectation_sha256'),@('composite-capture.json','capture_sha256'))){$p=Join-Path $case ('partial-metadata\'+$spec[0]);Need ((Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant() -ceq $originalPins[$spec[0]] -and $d.($spec[1]) -ceq $originalPins[$spec[0]]) 'Recovery pins differ from original949 closed metadata.'}
$request=Read-HostJson (Join-Path $case 'partial-metadata\request.json');$backing=Read-HostJson (Join-Path $case 'partial-metadata\compact-backing.json')
Need ($request.experiment_id -ceq $original -and $request.comparison.source_sha256 -ceq 'a90a9cd8f9fca6037b396127d161f56cc5698cae832c6bd3872d38378a367c6e' -and $d.packed_sha256 -ceq $backing.artifact.packed_sha256) 'Original source/declared packed identity differs.'
$old=@($enrollment.old_checkpoint_ids|ForEach-Object {([guid]$_).ToString('D')});Need ($old.Count -eq $ExpectedCheckpointCount -and @($old|Sort-Object -Unique).Count -eq $ExpectedCheckpointCount -and $partial.ToString('D') -in $old) 'Supplied complete checkpoint set differs.'
if($Operation -ceq 'Rollback'){$resumed=Read-HostJson (Join-Path $base 'compact-admitted-recovery-20261028\finalize\preserved-checkpoint.json');Need ($resumed.success -eq $true -and $resumed.operation -ceq 'Finalize' -and $resumed.checkpoint_count -eq 46 -and $resumed.checkpoint_id -in $old) 'Preserved resumed46 must exist before the separately restored rollback fork.'}
Import-Module (Join-Path $PSScriptRoot 'Lab.psm1') -Force
$config=Get-LabConfiguration -WorkspaceRoot $workspace;$capacity=Get-LabCapacity -Configuration $config
Need ($capacity.MaximumActualBytes -eq 329374052988 -and $capacity.MinimumFreeBytes -eq 17179869184) 'Storage epoch differs; never reset the50-GB allowance.';Assert-LabCapacity -Capacity $capacity -AdditionalBytes 512MB
$vm=Get-VM -Id $id;$snap=@(Get-VMSnapshot -VM $vm)
Need ($vm.Name -ceq 'ntfs2refs-streaming-v2-20261027' -and $vm.State.ToString() -ceq 'Running' -and $vm.ParentSnapshotId -eq $ExpectedParentGuid -and $vm.MemoryStartup -eq 4GB -and -not$vm.DynamicMemoryEnabled -and @(Get-VMNetworkAdapter -VM $vm).Count -eq 0 -and $snap.Count -eq $ExpectedCheckpointCount -and @($old|Where-Object {$_ -notin @($snap.Id|ForEach-Object {$_.ToString('D')})}).Count -eq 0) 'Exact running recovery branch/all prior snapshots required.'
$guard={param($DispatchJson)
    Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$d=$DispatchJson|ConvertFrom-Json
    $task=Get-ScheduledTask -TaskName $d.task_name -ErrorAction Stop;$info=Get-ScheduledTaskInfo -TaskName $d.task_name -ErrorAction Stop
    if($task.State.ToString() -cne 'Ready' -or $info.LastTaskResult -ne 0 -or $info.LastRunTime.Year -lt 2026){throw 'Recovery is not terminal0; do not preserve/shutdown.'}
    $arguments=(@($d.arguments)|ForEach-Object {if($_.Contains('"')){throw 'Quoted dispatch argument refused.'};'"'+$_+'"'}) -join ' '
    if(@($task.Actions).Count -ne 1 -or $task.Actions[0].Execute -cne $d.binary -or $task.Actions[0].Arguments -cne $arguments -or (Get-FileHash -LiteralPath $d.binary).Hash.ToLowerInvariant() -cne $d.binary_sha256){throw 'Actual terminal task/action/binary differs.'}
    if(@(Get-CimInstance Win32_Process -ErrorAction Stop|Where-Object {$_.Name -in @('lab-recover-native-composite.exe','lab-convert-native-composite.exe','lab-abort-general-source.exe','ntfs2refs.exe','ntfs2refs-recover.exe','ntfs2refs-bind.exe','lab-apply-compact-fixture.exe','lab-verify-general-converted.exe','lab-general-refs-mutation.exe')}).Count -or @(Get-ScheduledTask -ErrorAction Stop|Where-Object {$_.TaskName -like 'N2R-*' -and $_.State.ToString() -in @('Running','Queued')}).Count){throw 'A project native worker or scheduled wrapper remains active.'}
    $source=Get-Disk -Number 1;$shadow=Get-Disk -Number 3;$p=Get-Partition -DiskNumber 1 -PartitionNumber 2;$v=$p|Get-Volume
    $fs=if($d.operation -ceq 'Finalize'){'ReFS'}else{'NTFS'};$cluster=if($d.operation -ceq 'Finalize'){4096}else{65536}
    if([guid]$source.Guid -ne [guid]'1b191872-c372-41ee-a416-e18863996f54' -or $source.IsOffline -or $source.IsReadOnly -or [guid]$p.Guid -ne [guid]'f06075a8-67a2-46b9-8fac-4af4da809617' -or $p.Offset -ne 16MB -or $p.Size -ne 52GB -or [guid]$shadow.Guid -ne [guid]'c0f2cd39-ad3d-484e-9990-0e6eba74485f' -or -not$shadow.IsOffline -or -not$shadow.IsReadOnly -or $v.FileSystem -cne $fs -or $v.AllocationUnitSize -ne $cluster -or $v.FileSystemLabel -cne 'n2r-stream-source'){throw 'Completed native source0/shadow3 filesystem/label differs.'}
    @{task=$d.task_name;exit=0;native_workers_absent=$true;source_filesystem=[string]$v.FileSystem;source_cluster_bytes=$v.AllocationUnitSize;source_label=[string]$v.FileSystemLabel;source_offline=$false;source_readonly=$false;shadow_offline=$true;shadow_readonly=$true;utc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Compress
}
$s=$null;$intentSaved=$false;$dispatchJson=$d|ConvertTo-Json -Depth 10 -Compress
try{
    $s=New-PSSession -VMId $id -Credential (Import-Clixml (Join-Path $workspace '.lab\hyperv\win11\secrets\guest-credential.xml')) -ErrorAction Stop
    $terminal=Invoke-Command -Session $s -ScriptBlock $guard -ArgumentList $dispatchJson|ConvertFrom-Json
    Save-New 'preservation-intent.json' @{operation=$Operation;run_id=$d.run_id;original_run_id=$original;vm_id=$id.ToString();parent_before_creation=$ExpectedParentGuid.ToString('D');old_checkpoint_ids=$old;terminal=$terminal;capacity=$capacity;allowance_bytes=512MB;script_sha256=(Get-FileHash -LiteralPath $PSCommandPath).Hash.ToLowerInvariant();restore_boot_force_authorized=$false;utc=[DateTime]::UtcNow.ToString('o')};$intentSaved=$true
    $text=Invoke-Command -Session $s -ArgumentList $dispatchJson -ScriptBlock {param($DispatchJson)
        Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$d=$DispatchJson|ConvertFrom-Json;$held=[Collections.Generic.List[IO.FileStream]]::new();$docs=[Collections.Generic.List[object]]::new();$values=@{};$pins=@{};$total=[long]0
        try{foreach($name in @('request.json','ticket.json','expectation.json','intent.json','input-identities.json','journal-identity.json','completion.json','result.json')+$(if($d.operation -ceq 'Rollback'){@('execution.json')}else{@()})){$path=Join-Path $d.output_dir $name;$m=Get-Item -LiteralPath $path -Force;if($m.PSIsContainer -or ($m.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $m.Length -le 0 -or $m.Length -gt 4MB){throw 'Bounded ordinary closed C metadata required.'};$ancestor=$m.Directory;while($null -ne $ancestor){if($ancestor.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Reparse metadata ancestry.'};$ancestor=$ancestor.Parent};$total+=$m.Length;if($total -gt 16MB){throw 'Closed metadata aggregate exceeds16MiB.'};$f=[IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$held.Add($f);$b=[byte[]]::new([int]$m.Length);$at=0;while($at -lt $b.Length){$n=$f.Read($b,$at,$b.Length-$at);if($n -eq 0){throw 'Short metadata read.'};$at+=$n};if($f.Length -ne $b.Length){throw 'Metadata changed.'};$sha=[Security.Cryptography.SHA256]::Create();try{$pin=[BitConverter]::ToString($sha.ComputeHash($b)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};$pins[$name]=$pin;$values[$name]=[Text.UTF8Encoding]::new($false,$true).GetString($b)|ConvertFrom-Json;$docs.Add(@{name=$name;bytes=$b.Length;sha256=$pin;bytes_base64=[Convert]::ToBase64String($b)})}
            if(Test-Path -LiteralPath (Join-Path $d.output_dir 'failed.json')){throw 'Failure artifact exists; preserve unresolved state without shutdown.'}
            $r=$values['request.json'];$c=$values['completion.json'];$result=$values['result.json'];$intent=$values['intent.json'];$expect=$values['expectation.json']
            if($pins['request.json'] -cne $d.request_sha256 -or $pins['ticket.json'] -cne $d.ticket_sha256 -or $pins['expectation.json'] -cne $d.expectation_sha256 -or $r.experiment_id -cne $d.original_run_id -or -not$c.success -or $null -ne $c.error -or $result.kind -cne 'experimental-compact-recovery' -or $result.success -isnot [bool] -or -not$result.success -or $result.operation -cne $d.operation.ToLowerInvariant() -or $intent.request_sha256 -cne $d.request_sha256 -or $intent.ticket_sha256 -cne $d.ticket_sha256 -or $intent.capture_sha256 -cne $d.capture_sha256 -or $intent.packed_sha256 -cne $d.packed_sha256){throw 'Completed recovery documents/pins disagree.'}
            if($d.operation -ceq 'Finalize'){
                if(-not$c.rollback_closed -or -not$result.rollback_closed -or $null -eq $c.handoff -or -not$c.handoff.handoff_recorded -or $c.handoff.operation -cne 'handoff-recorded' -or $c.handoff.target_sha256 -cne $r.comparison.shadow_sha256 -or @($c.native.native.objects).Count -ne 15 -or @($expect.objects).Count -ne 15 -or -not$c.mount_paths_preserved -or -not$c.label_restoration.success -or -not$c.label_restoration.readback_matches -or (($c.label_restoration.after.label.utf16 -join ',') -cne ($r.expected_source_label.utf16 -join ','))){throw 'Completed HND/native tree/label/mount proof missing.'}
                $hashes=0;foreach($object in $expect.objects){$match=@($c.native.native.objects|Where-Object {($_.components -join '\') -ceq ($object.path -join '\')});if($match.Count -ne 1){throw 'Expected native object missing/duplicated.'};if(-not$object.directory){if($match[0].logical_sha256 -cne $object.sha256){throw 'Complete native logical hash differs.'};$hashes++}};if($hashes -ne 10){throw 'All10 complete native stream hashes required.'};$scope='durable HND and native15-object/10-stream verification plus label/mount receipts; no current raw-image claim'
            }else{$x=$values['execution.json'];$original='a90a9cd8f9fca6037b396127d161f56cc5698cae832c6bd3872d38378a367c6e';if(-not$c.replay_closed -or $c.mounted_filesystem -cne 'NTFS' -or -not$result.ntfs_rollback_completed -or $r.comparison.source_sha256 -cne $original -or $x.expected_target_sha256 -cne $original -or $x.result.target_sha256 -cne $original -or $null -eq $c.marker -or $c.marker.operation -cne 'ntfs-rollback-complete' -or $c.marker.target_sha256 -cne $original){throw 'Exact original pre-mount image, closed ABT and native NTFS proof required.'};$scope='execution and ABT prove exact original before writable NTFS mount; native filesystem presence checked, no post-mount whole-image equality claim'}
            @{success=$true;operation=$d.operation;run_id=$d.run_id;scope=$scope;documents=$docs.ToArray();journal_or_packed_opened=$false;raw_recovery_authorized=$false}|ConvertTo-Json -Depth 6 -Compress
        }finally{for($i=$held.Count-1;$i -ge 0;$i--){$held[$i].Dispose()}}
    }
    $evidence=$text|ConvertFrom-Json;$archive=Join-Path $root 'closed-metadata';Need (-not(Test-Path -LiteralPath $archive)) 'Role metadata archive exists.';New-Item -ItemType Directory -Path $archive|Out-Null
    $pins=@();foreach($doc in $evidence.documents){Need ($doc.name -cmatch '\A[a-z-]+\.json\z') 'Unexpected archive leaf.';$b=[Convert]::FromBase64String($doc.bytes_base64);Need ($b.Length -eq $doc.bytes -and (Hash $b) -ceq $doc.sha256) 'Transported metadata pin differs.';$f=[IO.File]::Open((Join-Path $archive $doc.name),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$f.Write($b,0,$b.Length);$f.Flush($true)}finally{$f.Dispose()};$pins+=@{name=$doc.name;bytes=$b.Length;sha256=$doc.sha256}}
    $evidence.documents=$pins;Save-New 'closed-metadata-pins.json' $evidence
    $terminal=Invoke-Command -Session $s -ScriptBlock $guard -ArgumentList $dispatchJson|ConvertFrom-Json;Save-New 'pre-shutdown-terminal.json' $terminal;Remove-PSSession $s;$s=$null
    $vm=Get-VM -Id $id;Need ($vm.State.ToString() -ceq 'Running' -and $vm.ParentSnapshotId -eq $ExpectedParentGuid) 'Owned branch changed before clean shutdown.';Assert-LabCapacity -Capacity (Get-LabCapacity -Configuration $config) -AdditionalBytes 256MB
    Save-New 'shutdown-intent.json' @{vm_id=$id.ToString();parent_id=$vm.ParentSnapshotId.ToString('D');native_workers_absent=$true;force=$false;utc=[DateTime]::UtcNow.ToString('o')};Stop-VM -VM $vm -Confirm:$false -ErrorAction Stop
    $deadline=[DateTime]::UtcNow.AddSeconds(30);do{$fresh=Get-VM -Id $id;if($fresh.State.ToString() -ceq 'Off' -and $fresh.MemoryAssigned -eq 0){break};if([DateTime]::UtcNow -ge $deadline){throw 'Fresh clean OFF did not settle; never force/repeat stop.'};Start-Sleep -Milliseconds 500}while($true)
    $parentBefore=$fresh.ParentSnapshotId.ToString('D');Need ([guid]$parentBefore -eq $ExpectedParentGuid) 'OFF lineage differs.';$name='streaming-v2-admitted-compact-'+$Operation.ToLowerInvariant()+'-passed';$before=@(Get-VMSnapshot -VM (Get-VM -Id $id));Need ($before.Count -eq $ExpectedCheckpointCount -and @($old|Where-Object {$_ -notin @($before.Id|ForEach-Object {$_.ToString('D')})}).Count -eq 0 -and @($before|Where-Object Name -CEQ $name).Count -eq 0) 'Fresh checkpoint intent requires unchanged complete prior set/name.'
    Save-New 'checkpoint-create-intent.json' @{vm_id=$id.ToString();operation=$Operation;run_id=$d.run_id;name=$name;parent_before_creation=$parentBefore;prior_checkpoint_ids=$old;creation_issued_at_most_once=$true;utc=[DateTime]::UtcNow.ToString('o')};$created=Checkpoint-VM -VM (Get-VM -Id $id) -SnapshotName $name -Passthru -ErrorAction Stop;$direct=if($null -ne $created -and [guid]$created.Id -ne [guid]::Empty){$created.Id.ToString('D')}else{$null}
    $deadline=[DateTime]::UtcNow.AddSeconds(30);do{$fresh=Get-VM -Id $id;$all=@(Get-VMSnapshot -VM $fresh);$match=@($all|Where-Object Name -CEQ $name);Need ($match.Count -le 1) 'Duplicate checkpoint name; preserve uncertainty.';if($match.Count -eq 1 -and $all.Count -eq $ExpectedCheckpointCount+1 -and @($old|Where-Object {$_ -notin @($all.Id|ForEach-Object {$_.ToString('D')})}).Count -eq 0){$cp=$match[0].Id.ToString('D');Need (($null -eq $direct -or $direct -ceq $cp) -and $cp -notin $old -and $fresh.State.ToString() -ceq 'Off' -and $fresh.MemoryAssigned -eq 0) 'Saved checkpoint/OFF identity differs.';break};if([DateTime]::UtcNow -ge $deadline){throw 'Fresh snapshot view did not settle in30s; no checkpoint retry permitted.'};Start-Sleep -Milliseconds 500}while($true)
    Save-New 'preserved-checkpoint.json' @{success=$true;operation=$Operation;run_id=$d.run_id;original_run_id=$original;vm_id=$id.ToString();checkpoint_id=$cp;parent_id=$parentBefore;checkpoint_count=$all.Count;all_prior_preserved=$true;state='Off';memory_assigned=0;scope=$evidence.scope;journal_or_packed_read=$false;raw_recovery_authorized=$false;utc=[DateTime]::UtcNow.ToString('o')};Get-Content -LiteralPath (Join-Path $root 'preserved-checkpoint.json') -Raw
}catch{if($intentSaved -and -not(Test-Path -LiteralPath (Join-Path $root 'preservation-failed.json'))){Save-New 'preservation-failed.json' @{operation=$Operation;run_id=$d.run_id;error=$_.Exception.ToString();automatic_retry=$false;utc=[DateTime]::UtcNow.ToString('o')}};throw}
finally{if($null -ne $s){Remove-PSSession $s}}
